package com.guocheng.mediapocket;
import org.json.*;import java.util.*;
public final class AggregateRulesTest {
 static void check(boolean ok,String what){if(!ok)throw new AssertionError(what);}
 public static void main(String[] a)throws Exception{
  JSONObject emby=new JSONObject().put("name","繁花").put("year","2023").put("emby.server","s1");
  JSONObject tv=new JSONObject().put("name","繁花 第一季").put("fusion.site","x");
  JSONObject st=new JSONObject().put("name","Oppenheimer").put("releaseInfo","2023");
  JSONObject st2=new JSONObject().put("name","繁花").put("releaseInfo","1990");
  check(AggregateRules.source(emby).equals("emby")&&AggregateRules.source(tv).equals("tvbox")&&AggregateRules.source(st).equals("stremio"),"source");
  check(AggregateRules.key("繁花 第一季").equals(AggregateRules.key("繁花"))&&AggregateRules.key("Dune: Part Two").equals("dunepasttwo".replace("pas","par")),"key");
  check(AggregateRules.year(st)==2023&&AggregateRules.year(new JSONObject())==0,"year");
  JSONArray merged=AggregateRules.merge(Arrays.asList(new JSONArray().put(emby),new JSONArray().put(tv).put(new JSONObject().put("name","漫长的季节").put("fusion.site","x")),new JSONArray().put(st).put(st2)),20);
  check(merged.length()==4,"merged count "+merged.length());
  check(merged.getJSONObject(0).optString("agg.source").equals("emby")&&merged.getJSONObject(0).optInt("agg.count")==2,"dedupe keeps emby, counts tvbox");
  check(merged.getJSONObject(1).optString("name").equals("漫长的季节")||merged.getJSONObject(1).optString("name").equals("Oppenheimer"),"round robin");
  boolean old=false;for(int i=0;i<merged.length();i++)if(merged.getJSONObject(i).optString("releaseInfo").equals("1990"))old=true;check(old,"different year not merged");
  check(AggregateRules.merge(Arrays.asList(null,new JSONArray()),20).length()==0,"empty");
  check(AggregateRules.rowForCategory("每日更新").equals("fresh")&&AggregateRules.rowForCategory("国产动漫").equals("anime")&&AggregateRules.rowForCategory("电视剧").equals("series")&&AggregateRules.rowForCategory("电影").equals("movie")&&AggregateRules.rowForCategory("纪录片").equals("doc")&&AggregateRules.rowForCategory("综艺").isEmpty(),"categories");
  JSONArray resume=AggregateRules.resume(new JSONArray().put(new JSONObject().put("id","e1").put("name","三体")),new JSONArray().put(new JSONObject().put("id","tt1").put("name","三体")).put(new JSONObject().put("id","tt2").put("name","奥本海默")));
  check(resume.length()==2&&resume.getJSONObject(0).optString("id").equals("e1"),"resume dedupe");
  check(AggregateRules.stale(0,1000)&&!AggregateRules.stale(1000,2000)&&AggregateRules.stale(0,AggregateRules.FRESH_MS+5),"stale");
  JSONObject dune=new JSONObject().put("name","沙丘").put("year","2021").put("poster","keep").put("emby.server","s");
  JSONObject dune2=new JSONObject().put("name","沙丘").put("year","2021").put("fusion.site","f");
  JSONArray once=AggregateRules.merge(Arrays.asList(new JSONArray().put(dune),new JSONArray().put(dune2)),5);
  check(once.length()==1&&once.getJSONObject(0).optInt("agg.count")==2&&"keep".equals(dune.optString("poster"))&&!dune.has("agg.source"),"dedupe keeps source object, count 2");
  JSONObject copy=AggregateRules.copy(dune);copy.put("poster","");check("keep".equals(dune.optString("poster"))&&"".equals(copy.optString("poster")),"shallow copy");
  List<JSONArray> bench=new ArrayList<>();
  for(int s=0;s<4;s++){JSONArray list=new JSONArray();for(int i=0;i<30;i++)list.put(new JSONObject().put("name","片"+s+"-"+i).put("year",String.valueOf(2000+(i%5))));bench.add(list);}
  long started=System.nanoTime();for(int n=0;n<80;n++)check(AggregateRules.merge(bench,20).length()==20,"bench size");
  long ms=(System.nanoTime()-started)/1000000L;check(ms<1500,"merge 80x4x30 took "+ms+"ms");
  check(AggregateRules.rowForCategory("最新动漫").equals("anime")&&AggregateRules.rowForCategory("最新电影").equals("movie")&&AggregateRules.rowForCategory("每日更新").equals("fresh"),"latest categories");
  JSONObject anim=new JSONObject().put("name","X").put("type","movie").put("genres",new JSONArray().put("Animation"));
  JSONObject documentary=new JSONObject().put("name","Y").put("type","movie").put("genres",new JSONArray().put("纪录片"));
  JSONObject forced=new JSONObject().put("name","Z").put("type","movie");
  check(AggregateRules.rowForEmby(anim,"电影","movies").equals("anime")&&AggregateRules.rowForEmby(documentary,"电影","movies").equals("doc")&&AggregateRules.rowForEmby(forced,"动漫","tvshows").equals("anime"),"emby genre and library");
  check(EmbyApi.library(new JSONObject().put("Name","国漫").put("CollectionType","anime"))&&EmbyApi.library(new JSONObject().put("CollectionType","movies"))&&!EmbyApi.library(new JSONObject().put("Name","音乐").put("CollectionType","music")),"anime library kept, music dropped");
  check(AggregateRules.key("Dune: Part Two").equals("duneparttwo"),"public key keeps part two");
  JSONObject dune1984=new JSONObject().put("name","沙丘").put("year","1984");JSONObject dune2021=new JSONObject().put("name","沙丘 (2021)");
  check(!AggregateRules.same(dune1984,dune2021),"remake years stay apart");
  JSONObject sequel=new JSONObject().put("name","沙丘2").put("fusion.site","f");JSONObject first=new JSONObject().put("name","沙丘").put("year","2021").put("emby.server","s").put("id","s0");
  check(!AggregateRules.same(sequel,first)&&!AggregateRules.same(new JSONObject().put("name","沙丘续集"),first)&&!AggregateRules.same(new JSONObject().put("name","沙丘 II"),first)&&!AggregateRules.same(new JSONObject().put("name","沙丘 第二部"),first),"sequel without year not merged");
  JSONArray seq=AggregateRules.merge(Arrays.asList(new JSONArray().put(first),new JSONArray().put(sequel)),5);check(seq.length()==2,"sequel stays in the row");
  check(AggregateRules.same(emby,tv),"繁花 and 繁花 第一季 still merge");
  JSONObject bare=new JSONObject().put("name","沙丘").put("year","2021").put("emby.server","s").put("id","win");
  JSONObject richer=new JSONObject().put("name","沙丘").put("year","2021").put("fusion.site","f").put("poster","pic").put("description","简介").put("background","wide");
  JSONArray filled=AggregateRules.merge(Arrays.asList(new JSONArray().put(bare),new JSONArray().put(richer)),5);
  check(filled.length()==1&&filled.getJSONObject(0).optString("poster").equals("pic")&&filled.getJSONObject(0).optString("description").equals("简介")&&filled.getJSONObject(0).optString("background").equals("wide"),"fill poster and description");
  check(filled.getJSONObject(0).optString("emby.server").equals("s")&&!filled.getJSONObject(0).has("fusion.site")&&filled.getJSONObject(0).optString("agg.source").equals("emby")&&!bare.has("agg.source"),"play entry stays with the winner");
  Set<String> shownIds=new HashSet<>();List<AggregateRules.Ident> shown=new ArrayList<>();
  AggregateRules.collectShown(new JSONArray().put(new JSONObject().put("id","1").put("name","沙丘").put("year","2021")),shownIds,shown);
  JSONArray movies=new JSONArray().put(new JSONObject().put("id","1").put("name","沙丘").put("year","2021")).put(new JSONObject().put("id","2").put("name","奥本海默").put("year","2023")).put(new JSONObject().put("id","x").put("name","沙丘").put("year","2021"));
  JSONArray left=AggregateRules.withoutShown(movies,shownIds,shown);check(left.length()==1&&left.getJSONObject(0).optString("id").equals("2"),"later row skips earlier id and title");
  JSONArray resumeCards=AggregateRules.resume(new JSONArray().put(new JSONObject().put("id","e1").put("name","三体").put("emby.server","s")),new JSONArray().put(new JSONObject().put("id","tt1").put("name","三体 · 第3集")));
  check(resumeCards.length()==1&&resumeCards.getJSONObject(0).optString("id").equals("e1"),"resume title strips episode");
  JSONArray serverA=new JSONArray().put(new JSONObject().put("id","a").put("name","甲").put("emby.server","1"));JSONArray serverB=new JSONArray().put(new JSONObject().put("id","b").put("name","乙").put("emby.server","2"));
  JSONArray ordered=AggregateRules.orderedResume(Arrays.asList(serverB,serverA),new JSONArray().put(new JSONObject().put("id","c").put("name","甲 · 第2集")).put(new JSONObject().put("id","d").put("name","丙")));
  check(ordered.length()==3&&ordered.getJSONObject(0).optString("id").equals("b")&&ordered.getJSONObject(1).optString("id").equals("a")&&ordered.getJSONObject(2).optString("id").equals("d"),"servers keep list order");
  check(AggregateRules.almostFinished(90,100)&&!AggregateRules.almostFinished(50,100)&&!AggregateRules.almostFinished(10,0),"almost finished");
  JSONObject cont=new JSONObject().put("id","r").put("name","继续").put("poster","p").put("background","p").put("emby.server","s");
  JSONObject land=new JSONObject().put("id","e").put("name","横图").put("poster","p").put("background","b").put("emby.server","s").put("type","movie");
  JSONObject played=new JSONObject().put("id","d").put("name","看完").put("poster","p").put("background","b").put("emby.played",true).put("emby.server","s");
  JSONObject port=new JSONObject().put("id","v").put("name","竖图").put("poster","p").put("background","p").put("emby.server","s");
  JSONObject stream=new JSONObject().put("id","st").put("name","流媒体").put("poster","p").put("background","wide").put("type","movie");
  JSONArray heroes=AggregateRules.pickHomeHeroes(new JSONArray().put(cont),new JSONArray().put(played).put(port).put(land),new JSONArray(),new JSONArray().put(stream),true);
  check(heroes.length()==2&&heroes.getJSONObject(0).optString("id").equals("r")&&heroes.getJSONObject(0).optString("agg.hero").equals("resume")&&heroes.getJSONObject(1).optString("id").equals("e")&&heroes.getJSONObject(1).optString("agg.source").equals("emby"),"hero keeps one resume and emby landscape");
  check(AggregateRules.pickHomeHeroes(new JSONArray(),new JSONArray(),new JSONArray(),new JSONArray().put(stream),false).length()==0,"stremio waits until others finish");
  JSONArray fallback=AggregateRules.pickHomeHeroes(new JSONArray(),new JSONArray().put(port),new JSONArray(),new JSONArray().put(stream),true);
  check(fallback.length()==1&&fallback.getJSONObject(0).optString("id").equals("st")&&fallback.getJSONObject(0).optString("agg.source").equals("stremio"),"stremio fallback");
  JSONArray onlyResume=AggregateRules.pickHomeHeroes(new JSONArray().put(cont),new JSONArray(),new JSONArray(),new JSONArray().put(stream),true);
  check(onlyResume.length()==1&&onlyResume.getJSONObject(0).optString("agg.hero").equals("resume"),"emby continue blocks stremio");
  JSONArray idsA=new JSONArray().put(new JSONObject().put("id","1")).put(new JSONObject().put("id","2"));
  JSONArray idsB=new JSONArray().put(new JSONObject().put("id","1")).put(new JSONObject().put("id","2"));
  JSONArray idsC=new JSONArray().put(new JSONObject().put("id","1")).put(new JSONObject().put("id","9"));
  JSONArray idsD=new JSONArray().put(new JSONObject().put("id","1")).put(new JSONObject().put("id","2")).put(new JSONObject().put("id","3"));
  check(AggregateRules.sameHeroIds(idsA,idsB)&&!AggregateRules.sameHeroIds(idsA,idsC)&&!AggregateRules.sameHeroIds(idsA,idsD),"hero ids");
  check(AggregateRules.heroKicker(new JSONObject().put("agg.hero","resume").put("agg.source","tvbox")).equals("继续观看 · 影视仓")&&AggregateRules.heroKicker(new JSONObject().put("agg.hero","new").put("agg.source","emby")).equals("推荐 · EMBY"),"kicker");
  long nowNs=1000000000L;check(AggregateRules.waitMs(0,0,30000)==30000&&AggregateRules.waitMs(nowNs+5000000000L,nowNs,30000)==5000&&AggregateRules.waitMs(nowNs,nowNs+1000000L,30000)==0&&AggregateRules.waitMs(nowNs+60000000000L,nowNs,30000)==30000,"wait budget");
  check(AggregateRules.epoch("2024-06-01")>AggregateRules.epoch("2020")&&AggregateRules.epoch("")==0&&AggregateRules.timeOf(new JSONObject().put("agg.time",5L))==5L,"epoch");
  JSONObject fav=new JSONObject().put("id","fav").put("name","收藏片").put("emby.server","s").put("agg.time",1);
  JSONObject newer=new JSONObject().put("id","n").put("name","新片").put("emby.server","s").put("agg.time",300);
  JSONObject older=new JSONObject().put("id","o").put("name","旧片").put("emby.server","s").put("agg.time",100);
  JSONObject warehouse=new JSONObject().put("id","t").put("name","仓片").put("fusion.site","x").put("agg.time",200);
  JSONObject finished=new JSONObject().put("id","f").put("name","完片").put("emby.server","s").put("agg.time",400).put("agg.finished",true);
  Set<String> favs=new HashSet<>();AggregateRules.markKey(favs,fav);
  JSONArray freshOrder=AggregateRules.merge(Arrays.asList(new JSONArray().put(older).put(newer).put(fav).put(finished),new JSONArray().put(warehouse)),10,new AggregateRules.Mix(true,favs,null));
  check(freshOrder.length()==5&&freshOrder.getJSONObject(0).optString("id").equals("fav")&&freshOrder.getJSONObject(1).optString("id").equals("n")&&freshOrder.getJSONObject(2).optString("id").equals("t")&&freshOrder.getJSONObject(3).optString("id").equals("o")&&freshOrder.getJSONObject(4).optString("id").equals("f")&&freshOrder.getJSONObject(4).optBoolean("agg.finished"),"fresh sort");
  JSONObject normalA=new JSONObject().put("id","a").put("name","甲").put("emby.server","s");
  JSONObject normalDone=new JSONObject().put("id","b").put("name","乙").put("emby.server","s").put("agg.finished",true);
  JSONObject normalC=new JSONObject().put("id","c").put("name","丙").put("fusion.site","x");
  JSONArray plain=AggregateRules.merge(Arrays.asList(new JSONArray().put(normalA).put(normalDone),new JSONArray().put(normalC)),10,new AggregateRules.Mix(false,null,null));
  check(plain.length()==3&&plain.getJSONObject(0).optString("id").equals("a")&&plain.getJSONObject(1).optString("id").equals("c")&&plain.getJSONObject(2).optString("id").equals("b"),"finished sinks, sources alternate");
  JSONArray cats=new JSONArray().put(new JSONObject().put("type_name","最新动漫").put("type_id","dm")).put(new JSONObject().put("type_name","电影").put("type_id","m1")).put(new JSONObject().put("type_name","最新电影").put("type_id","m2")).put(new JSONObject().put("type_name","每日更新").put("type_id","day"));
  Map<String,JSONArray> grouped=AggregateRules.groupCategories(cats);
  check(grouped.get("anime").length()==1&&grouped.get("anime").getJSONObject(0).optString("type_id").equals("dm")&&grouped.get("movie").length()==2&&grouped.get("fresh").getJSONObject(0).optString("type_id").equals("day"),"all matching categories");
  int movieAt=-1,freshAt=-1,at=0;for(String k:grouped.keySet()){if(k.equals("movie"))movieAt=at;if(k.equals("fresh"))freshAt=at;at++;}check(movieAt>=0&&freshAt>movieAt,"movies fetched before daily");
  System.out.println("PASS: aggregate rows, sequel guard, hero pick, resume order, sort, round-robin, "+ms+"ms for 80 merges.");
 }
}
